@Tag("UnitTest")
public class HyphenationTreeTest extends ExtendedITextTest {

    private static final String SOURCE_FOLDER = "./src/test/resources/com/itextpdf/layout/HyphenationTreeTest/";

    @Test
    public void loadPatternXmlTest() throws HyphenationException, IOException {
        String sourceFilePath = SOURCE_FOLDER + "hyphen_pattern.xml";
        HyphenationTree hyphenationTree = new HyphenationTree();
        hyphenationTree.loadPatterns(sourceFilePath);
        Assertions.assertEquals(3, hyphenationTree.length);
    }

    @Test
    public void directlyParsePatternClassesTest() throws HyphenationException, IOException, SAXException {
        String sourceFilePath = SOURCE_FOLDER + "only_classes.xml";
        String classPatterns = "\u0000a\u0000Ab\u0000B\u0000c\u0000C\u0000d\u0000D";

        HyphenationTree hyphenationTree = new HyphenationTree();
        PatternParser patternParser = new PatternParser(hyphenationTree);
        patternParser.parse(sourceFilePath);

        char[] sc = hyphenationTree.classmap.sc;
        String resultClassmapSc = new String(sc);
        Assertions.assertTrue(resultClassmapSc.contains(classPatterns));
    }
}

