        Assertions.assertEquals(100, document.getNumberOfPages(), "Page count");

        String contentTemplate = "q\n" +
                "BT\n" +
                "36 700 Td\n" +
                "/F1 72 Tf\n" +
                "({0})Tj\n" +
                "ET\n" +
                "Q\n" +
