        PdfDocument pdfDocument = new PdfDocument(new PdfReader(inPdf));
        SignatureUtil signatureUtil = new SignatureUtil(pdfDocument);

        Assertions.assertFalse(signatureUtil.signatureCoversWholeDocument("Signature1"));
    }

